import {EQUIPMENT,MATERIALS} from './equipment-catalog.js';
import {eligibility,experimentGraph,experimentById} from './experiment-definitions.js';
export const escapeText=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function requirementDetails(player,e){const r=eligibility(player,e.id),parents=experimentGraph().edges.filter(edge=>edge.to===e.id&&edge.type==='equipment');const connections=parents.map(edge=>`<p><strong>${edge.from==='starter'?'From your starter kit':'Equipment shared with '+escapeText(experimentById(edge.from).name)}</strong>${Object.keys(edge.equipment).length?': add '+Object.entries(edge.equipment).map(([id,n])=>`${n} × ${escapeText(EQUIPMENT[id].name)}`).join(', '):': no additional reusable equipment'}.</p>`).join('');return `<h3>${escapeText(e.name)}</h3><p>${escapeText(e.objective)}</p><p><strong>${r.label}</strong>${r.completed&&!r.available?' · restock requirements still apply':''}</p>${connections}<h4>Reusable equipment</h4><ul>${Object.entries(e.equipment).map(([id,n])=>`<li>${EQUIPMENT[id].name} × ${n} · owned ${player.equipment[id]||0}${r.missingEquipment[id]?' · missing '+r.missingEquipment[id]:''}</li>`).join('')}</ul><h4>Consumable supplies</h4><ul>${Object.entries(e.materials).map(([id,n])=>`<li>${MATERIALS[id].name} × ${n} · owned ${player.materials[id]||0}${r.missingMaterials[id]?' · missing '+r.missingMaterials[id]:''}</li>`).join('')}</ul>${r.prerequisites.length?'<p>Prerequisites: '+r.prerequisites.map(escapeText).join(', ')+'</p>':''}<p>${e.assemblies.map(escapeText).join(' ')}</p>${e.facilities?.length?'<p>Provided facilities / bundled parts: '+e.facilities.map(escapeText).join('; ')+'</p>':''}`;}
